/**
 * Continuous Innovation (SPEC-253) — the pure half of `/ci`: ordering, grouping,
 * the contents list, and the inline-mark tokenizer the reader renders with
 * elements instead of `innerHTML`. Content comes from `lib/ci/content.ts`
 * (generated by `tools/build_ci_content.py`).
 */

import type { CiKind, CiLine, CiPair, CiReport, CiSection } from "@/lib/ci/types";

/* ── the Reports | Plans bar (SPEC-272) ─────────────────────────────────── */

export type CiTab = "reports" | "plans";

export const CI_TABS: { key: CiTab; label: string; href: string }[] = [
  { key: "reports", label: "Reports", href: "/ci" },
  { key: "plans", label: "Plans", href: "/ci/plans" },
];

/** `/ci` → reports · `/ci/plans` → plans · anything else (a report, a plan) → null:
 * those own their title and render bare under the shell. */
export function ciTabFor(pathname: string): CiTab | null {
  const clean = pathname.replace(/\/+$/, "");
  if (clean === "/ci") return "reports";
  if (clean === "/ci/plans") return "plans";
  return null;
}

export const KIND_LABEL: Record<CiKind, string> = {
  engagement: "Engagement report",
  weekly: "Weekly build report",
  daily: "Daily build report",
};

/** SPEC-369: the generated reports plus the ones written since Sep 26 from the record. A
 * generated report wins on an id clash, so re-running the source project's generator can never
 * show a day twice. */
export function mergeReports(generated: CiReport[], recent: CiReport[]): CiReport[] {
  const taken = new Set(generated.map((report) => report.id));
  return [...generated, ...recent.filter((report) => !taken.has(report.id))];
}

/** The engagement report first, then everything newest first. */
export function orderReports(reports: CiReport[]): CiReport[] {
  return [...reports].sort((a, b) => {
    if (a.kind !== b.kind && (a.kind === "engagement" || b.kind === "engagement")) {
      return a.kind === "engagement" ? -1 : 1;
    }
    return b.sortDate.localeCompare(a.sortDate);
  });
}

const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

/** "September 2026" for a daily/weekly report; the engagement report is its own group. */
export function monthOf(report: CiReport): string {
  if (report.kind === "engagement") return "The whole engagement";
  const [y, m] = report.sortDate.split("-");
  return `${MONTHS[Number(m) - 1]} ${y}`;
}

export interface MonthGroup {
  month: string;
  reports: CiReport[];
}

/** Ordered groups for the feed and the date rail — engagement first, then months newest first. */
export function reportsByMonth(reports: CiReport[]): MonthGroup[] {
  const groups: MonthGroup[] = [];
  for (const r of orderReports(reports)) {
    const month = monthOf(r);
    const last = groups[groups.length - 1];
    if (last && last.month === month) last.reports.push(r);
    else groups.push({ month, reports: [r] });
  }
  return groups;
}

export function reportById(reports: CiReport[], id: string): CiReport | null {
  return reports.find((r) => r.id === id) ?? null;
}

export interface TocEntry {
  id: string;
  n: string;
  title: string;
}

/** One entry per section, plus the closing pages a report carries. */
export function tocFor(report: CiReport): TocEntry[] {
  const entries: TocEntry[] = report.sections.map((s) => ({ id: sectionAnchor(s), n: s.n, title: s.title }));
  if (report.pages.length > 0) entries.push({ id: "pages", n: "→", title: "The printed report" });
  if (report.tiers.length > 0) entries.push({ id: "before-after", n: "→", title: "Before and after" });
  if (report.next.length > 0) entries.push({ id: "next", n: "→", title: "Where this leaves us" });
  if (report.cautions.length > 0) entries.push({ id: "rules", n: "→", title: "The rules behind the work" });
  return entries;
}

export function sectionAnchor(section: CiSection): string {
  return `s-${section.n.replace(/[^0-9a-z]/gi, "")}`;
}

export type RichToken = { kind: "text" | "b" | "i" | "code"; text: string };

const MARK = /<(b|i|code)>([^]*?)<\/\1>/g;

/** Split a report string on its inline marks; anything else is plain text. */
export function richText(text: string): RichToken[] {
  const out: RichToken[] = [];
  let last = 0;
  for (const m of text.matchAll(MARK)) {
    const at = m.index ?? 0;
    if (at > last) out.push({ kind: "text", text: text.slice(last, at) });
    out.push({ kind: m[1] as "b" | "i" | "code", text: m[2] });
    last = at + m[0].length;
  }
  if (last < text.length) out.push({ kind: "text", text: text.slice(last) });
  return out;
}

/** The feed's counters. */
export function feedStats(reports: CiReport[]): { reports: number; screens: number; since: string } {
  const oldest = [...reports].sort((a, b) => a.sortDate.localeCompare(b.sortDate))[0];
  const screens = reports.reduce(
    (n, r) => n + r.sections.reduce((m, s) => m + s.shots.length, 0) + r.pages.length,
    0,
  );
  return { reports: reports.length, screens, since: oldest ? oldest.sortDate : "" };
}

/* ── the feed's filters and pages (SPEC-253 Patches) ─────────────────────── */

export const CI_PER_PAGE = 6;

export type CiKindFilter = "all" | CiKind;

export interface CiFilters {
  kind: CiKindFilter;
  /** A `monthOf()` value, or "all". */
  month: string;
  q: string;
}

export const DEFAULT_FILTERS: CiFilters = { kind: "all", month: "all", q: "" };

/** Filters straight off the URL — anything unknown falls back to the default. */
export function filtersFromParams(params: URLSearchParams): CiFilters {
  const kind = params.get("kind");
  return {
    kind: kind === "engagement" || kind === "weekly" || kind === "daily" ? kind : "all",
    month: params.get("month") || "all",
    q: (params.get("q") ?? "").trim(),
  };
}

/** Only what differs from the default goes into the URL. */
export function paramsFromFilters(filters: CiFilters, page: number): URLSearchParams {
  const params = new URLSearchParams();
  if (filters.kind !== "all") params.set("kind", filters.kind);
  if (filters.month !== "all") params.set("month", filters.month);
  if (filters.q) params.set("q", filters.q);
  if (page > 1) params.set("page", String(page));
  return params;
}

export function isDefaultFilters(filters: CiFilters): boolean {
  return filters.kind === "all" && filters.month === "all" && filters.q === "";
}

/** The month choices the reports actually cover, newest first. */
export function monthOptions(reports: CiReport[]): string[] {
  return reportsByMonth(reports)
    .map((g) => g.month)
    .filter((m) => m !== "The whole engagement");
}

/** Kind, month, and a case-insensitive search over hook, memo, period and area titles. */
export function filterReports(reports: CiReport[], filters: CiFilters): CiReport[] {
  const q = filters.q.trim().toLowerCase();
  return orderReports(reports).filter((r) => {
    if (filters.kind !== "all" && r.kind !== filters.kind) return false;
    if (filters.month !== "all" && monthOf(r) !== filters.month) return false;
    if (!q) return true;
    const hay = [r.hook, r.memo, r.period, ...r.sections.map((s) => s.title)].join(" ").toLowerCase();
    return hay.includes(q);
  });
}

export interface CiPage {
  items: CiReport[];
  page: number;
  pages: number;
  total: number;
}

/** Six a page; an out-of-range page clamps rather than 404s. */
export function paginate(reports: CiReport[], page: number, perPage = CI_PER_PAGE): CiPage {
  const total = reports.length;
  const pages = Math.max(1, Math.ceil(total / perPage));
  const current = Math.min(Math.max(1, Math.floor(page) || 1), pages);
  const start = (current - 1) * perPage;
  return { items: reports.slice(start, start + perPage), page: current, pages, total };
}

/** The first `n` area titles a card lists, and how many more there are. */
export function areasOf(report: CiReport, n = 3): { titles: string[]; more: number } {
  const titles = report.sections.slice(0, n).map((s) => s.title);
  return { titles, more: Math.max(0, report.sections.length - titles.length) };
}


/* ── the business view (SPEC-253 Patches) ─────────────────────────────────── */

export const CI_DETAIL_KEY = "ci:technical-detail";

/** The lines a view shows: every line with its full text when technical detail is on,
 * else the business lines with their scrubbed text. */
export function visibleLines(lines: CiLine[], technical: boolean): string[] {
  return technical ? lines.map((l) => l.full) : lines.filter((l) => !l.technical).map((l) => l.text);
}

export function visiblePairs(rows: CiPair[], technical: boolean): CiPair[] {
  return technical ? rows : rows.filter((r) => !r.technical);
}

/** How many lines the business view keeps out of sight for this report. */
export function hiddenCount(report: CiReport): number {
  const lines = report.sections.reduce((n, s) => n + s.inside.filter((l) => l.technical).length, 0);
  const subs = report.sections.filter((s) => s.sub && s.subTechnical).length;
  const pairs = [...report.next, ...report.cautions].filter((p) => p.technical).length;
  return lines + subs + pairs;
}
